        m.insert("ask".to_string(), self.safe_number_k(&bestAsk, "price", &[]));
        m.insert("askVolume".to_string(), self.safe_number_k(&bestAsk, "size", &[]));
        m.insert("vwap".to_string(), Value::Null);
        m.insert("open".to_string(), Value::Null);
