        let negRisk: Option<bool> = self.safe_bool_k(&params, "negRisk", &[self.safe_bool_k(&outcomeObj, "negRisk", &[Value::Bool(false)])]).as_bool();
        // maker-only: the CLOB rejects the order if it would immediately take
